import json,os
home=os.path.expanduser("~")
rep={"{HOME}":home,"{VAULT}":os.path.join(home,"SecondBrain"),"{DEV}":os.path.join(home,"DEV")}
d=json.load(open(os.path.join(home,"DEV/KeystoneOS/data/memory-index-paths.json")))
for p in d["paths"]:
    for k,v in rep.items(): p=p.replace(k,v)
    n=sum(len(f) for _,_,f in os.walk(p)) if os.path.isdir(p) else -1
